%#codegen
function k_out = calc_rice_k_fixpt(u_in, reset)
% CALC_RICE_K Dynamically estimates optimal Golomb-Rice parameter k
% using a power-of-two moving window sum and priority encoder (no division/log2).
%
% Backward-adaptive: computes k from past 8 samples so the decoder can
% independently track the exact same k without side-channel overhead.

fm = get_fimath();

WIN_SIZE = fi(8, 0, 4, 0, fm);   % Must be power of 2 (2^3)
INV_WIN  = fi(1/8, 0, 14, 16, fm); % Bit-shift right by 3 in fixed-point
K_MAX    = fi(8, 0, 4, 0, fm);   % Upper bound on Rice parameter k

persistent u_hist win_sum;

u_val = fi(double(u_in), 0, 10, 0, fm);

if isempty(u_hist) || reset
    % Initialize window with small default values (e.g., 4 -> initial k = 1)
    u_hist  = fi(repmat(4, fi_toint(WIN_SIZE), 1), 0, 10, 0, fm);
    win_sum = fi(fi(4, 0, 3, 0, fm) * WIN_SIZE, 0, 12, 0, fm);
end

% 1. Compute running mean of PAST window samples (shift right by 3)
avg_u = fi(floor(win_sum * INV_WIN), 0, 9, 0, fm);

% 2. Priority Encoder: Select k such that 2^k <= avg_u < 2^(k+1)
% Synthesizes to a fast parallel comparator tree (0 DSPs, 1 cycle)
if avg_u >= fi(256, 0, 9, 0, fm)
    k_out = fi(8, 0, 4, 0, fm);
elseif avg_u >= fi(128, 0, 8, 0, fm)
    k_out = fi(7, 0, 4, 0, fm);
elseif avg_u >= fi(64, 0, 7, 0, fm)
    k_out = fi(6, 0, 4, 0, fm);
elseif avg_u >= fi(32, 0, 6, 0, fm)
    k_out = fi(5, 0, 4, 0, fm);
elseif avg_u >= fi(16, 0, 5, 0, fm)
    k_out = fi(4, 0, 4, 0, fm);
elseif avg_u >= fi(8, 0, 4, 0, fm)
    k_out = fi(3, 0, 4, 0, fm);
elseif avg_u >= fi(4, 0, 3, 0, fm)
    k_out = fi(2, 0, 4, 0, fm);
elseif avg_u >= fi(2, 0, 2, 0, fm)
    %F2F: No information found for converting the following block of code
    %F2F: Start block
    k_out = fi(1, 0, 4, 0, fm);
    %F2F: End block
else
    %F2F: No information found for converting the following block of code
    %F2F: Start block
    k_out = fi(0, 0, 4, 0, fm);
    %F2F: End block
end

% Clamp to K_MAX
if k_out > K_MAX
    %F2F: No information found for converting the following block of code
    %F2F: Start block
    k_out = fi(K_MAX, 0, 4, 0, fm);
    %F2F: End block
end

% 3. Update sliding window sum & shift register for NEXT sample
oldest  = fi(u_hist(WIN_SIZE), 0, 10, 0, fm);
win_sum(:) = win_sum + u_val - oldest;

coder.hdl.loopspec('unroll');
for i = WIN_SIZE:fi(-1, 1, 2, 0, fm):fi(2, 0, 2, 0, fm)
    u_hist(i) = u_hist(i-fi(1, 0, 1, 0, fm));
end
u_hist(1) = u_val;
end



function y = fi_toint(u)
    coder.inline( 'always' );
    if isfi( u )
        nt = numerictype( u );
        s = nt.SignednessBool;
        wl = nt.WordLength;
        if s
            y = int32( fi( u, s, wl, 0, hdlfimath ) );
        else
            y = uint32( fi( u, s, wl, 0, hdlfimath ) );
        end
    else
        y = int32( u );
    end
end

function fm = get_fimath()
	fm = fimath('RoundingMethod', 'Floor',...
	     'OverflowAction', 'Wrap',...
	     'ProductMode','FullPrecision',...
	     'SumMode','FullPrecision');
end
